import React, {FC} from 'react'
import ListItemAction from 'src/app/components/Actions/ListItemAction'
import ViewAction from 'src/app/components/Actions/ViewAction'
import AntTable from 'src/app/components/Table/AntTable'
import {PurchaseOrderAction} from '../Actions/PurchaseOrder.actions'
import {DateTimeUtils} from 'src/app/utils'
import {useLang} from 'src/app/hooks/useLang'

const PurchaseOrderListing: FC<any> = (props) => {
  const {loading, listData, selectedRowKeys, handleOnChanged, handleTableChange, handleCallbackFunc} = props
  const {t} = useLang()

  const onCheckIsShowAction = (actionItemInfo: any, recordItemInfo: any): boolean => {
    if (
      actionItemInfo.title === 'Edit' &&
      ['SUBMITTED', 'REJECTED', 'APPROVED'].includes(recordItemInfo.process_status)
    ) {
      return false
    }
    if (
      actionItemInfo.title === 'Delete' &&
      ['SUBMITTED', 'BACKWARD_INITIATION', 'REJECTED', 'APPROVED'].includes(recordItemInfo.process_status)
    ) {
      return false
    }
    return true
  }

  const columns = [
    {
      dataIndex: 'po_number',
      key: 'po_number',
      title: t('PO Number'),
      sorter: true,
      width: '15%',
      render: (text: string, record: any, index: number) => (
        <ViewAction
          entityId={record.id}
          actionItem={PurchaseOrderAction.COMMON_ACTION.VIEW}
          defaultViewText={text}
          handleCallbackFunc={handleCallbackFunc}
        >
          <span className='grid-row-view-action fw-bolder cursor-pointer'>{text}</span>
        </ViewAction>
      ),
    },
    {
      dataIndex: 'supplier_id',
      key: 'supplier_id',
      title: t('Supplier'),
      width: '15%',
      render: (text: string, record: any) => record.supplier_name,
    },
    {
      dataIndex: 'order_date',
      key: 'order_date',
      title: t('Order Date'),
      sorter: true,
      width: '10%',
    },
    {
      dataIndex: 'po_status',
      key: 'po_status',
      title: t('PO Status'),
      width: '10%',
      render: (text: string) => <span className='text-capitalize'>{text}</span>,
    },
    {
      dataIndex: 'process_status',
      key: 'process_status',
      title: t('Approval Status'),
      sorter: true,
      width: '10%',
    },
    {
      dataIndex: 'created_by',
      key: 'created_by',
      title: t('Created By'),
      width: '10%',
      render: (text: string, record: any) => record.created_by_name,
    },
    {
      dataIndex: 'created_at',
      key: 'created_at',
      title: t('Created Time'),
      sorter: true,
      width: '10%',
      render: (value: any) => DateTimeUtils.formatDateTimeA(value),
    },
    {
      dataIndex: 'action',
      key: 'action',
      title: t('Action'),
      width: '10%',
      align: 'center',
      render: (text: string, record: any, index: number) => (
        <ListItemAction
          entity={record}
          entityId={record.id}
          actionList={PurchaseOrderAction.LIST_ITEM_ACTION}
          handleCallbackFunc={handleCallbackFunc}
          onCheckIsShowAction={onCheckIsShowAction}
        />
      ),
    },
  ]

  return (
    <div className='px-6'>
      <AntTable
        className='table-layout'
        rowSelection={false}
        rowSelectionPermission='auth:purchaseOrder:multiSelect'
        selectedRowKeys={selectedRowKeys}
        dataSource={listData}
        columns={columns}
        loading={loading}
        handleOnChanged={handleOnChanged}
        onChange={handleTableChange}
      />
    </div>
  )
}

export default React.memo(PurchaseOrderListing)
